import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils, Vector } from "../utils";
import { VisualMath } from "../math/VisualMath"; // SSOT Math import

export interface RenderCamera {
    x: number;
    y: number;
    zoom: number;
}

export class TacticalRenderer {
    private holoGlitchTimer = 0;
    private lastDirectorTarget = "";

    public update(dt: number, engine: GameEngine) {
        if (engine.directorTargetId !== this.lastDirectorTarget) {
            this.lastDirectorTarget = engine.directorTargetId || "";
            this.holoGlitchTimer = 0.3; 
        }
        if (this.holoGlitchTimer > 0) this.holoGlitchTimer -= dt;
    }

    public drawOverlay(ctx: CanvasRenderingContext2D, engine: GameEngine, highlight: Agent | null, grid: GridSystem, globalTime: number) {
        ctx.save();
        if (highlight && highlight.hp > 0) {
            const hH = grid.getTerrainHeight(highlight.q, highlight.r, engine);
            const startPx = highlight.px;
            const startPy = highlight.py - hH - 30; 
            if (highlight.trajectory.length > 0) {
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                highlight.trajectory.forEach(hex => {
                    const p = HexUtils.toPx(hex.q, hex.r, engine.mapConfig);
                    const h = grid.getTerrainHeight(hex.q, hex.r, engine);
                    ctx.lineTo(p.x, p.y - h - 30);
                });
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]); 
                ctx.globalAlpha = 0.6;
                ctx.stroke();
                ctx.setLineDash([]); 
                ctx.globalAlpha = 1.0;
                const dest = highlight.trajectory[highlight.trajectory.length - 1];
                const dP = HexUtils.toPx(dest.q, dest.r, engine.mapConfig);
                const dH = grid.getTerrainHeight(dest.q, dest.r, engine);
                ctx.save();
                ctx.translate(dP.x, dP.y - dH);
                ctx.scale(1, 0.6);
                ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.globalAlpha = 0.3; ctx.fill();
                ctx.strokeStyle = '#fff'; ctx.globalAlpha = 0.8; ctx.lineWidth=2; ctx.stroke();
                ctx.restore();
            }
            if (highlight.target && highlight.target.hp > 0) {
                const t = highlight.target;
                const tH = grid.getTerrainHeight(t.q, t.r, engine);
                const endPx = t.px;
                const endPy = t.py - tH - 30;
                const grad = ctx.createLinearGradient(startPx, startPy, endPx, endPy);
                const isEnemy = highlight.team !== t.team;
                const color = isEnemy ? '#ef4444' : '#4ade80';
                grad.addColorStop(0, 'rgba(0,0,0,0)'); 
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, color);
                ctx.beginPath();
                ctx.moveTo(startPx, startPy);
                ctx.lineTo(endPx, endPy);
                ctx.strokeStyle = grad;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.8 + Math.sin(globalTime * 10) * 0.2; 
                ctx.stroke();
                ctx.globalAlpha = 1.0;
            }
        }
        ctx.restore();
    }

    /**
     * SSOT Debugger: Visualizes the disparity between Logical State (Grid) and Physical State (Pixel)
     */
    public drawSSOTDebug(ctx: CanvasRenderingContext2D, engine: GameEngine, targetId: string, grid: GridSystem, globalTime: number) {
        const agent = engine.agents.find(a => a.id === targetId);
        if (!agent || agent.hp <= 0) return;

        ctx.save();
        ctx.lineWidth = 1;
        ctx.font = '10px monospace';

        // 1. LOGICAL ANCHOR (The "Truth" in Grid)
        const logicPos = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
        const logicH = grid.getTerrainHeight(agent.q, agent.r, engine);
        const logicY = VisualMath.getIsoVisualY(logicPos.y, logicH); // Surface

        ctx.strokeStyle = '#4ade80'; // Green = Logic
        ctx.fillStyle = '#4ade80';

        // Draw Logic Hex Center
        ctx.beginPath();
        ctx.arc(logicPos.x, logicY, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeRect(logicPos.x - 10, logicY - 10, 20, 20); // Box to show grid snap
        ctx.fillText(`LOGIC (${agent.q},${agent.r})`, logicPos.x + 12, logicY);

        // 2. PHYSICAL BODY (The "Visual" in Pixels)
        const physX = agent.px + agent.physics.x;
        const physY = VisualMath.getIsoVisualY(agent.py + agent.physics.y, agent.physics.z + logicH);

        ctx.strokeStyle = '#22d3ee'; // Cyan = Physics
        ctx.fillStyle = '#22d3ee';

        ctx.beginPath();
        ctx.arc(physX, physY, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(physX, physY, 12, 0, Math.PI * 2); // Hitbox hint
        ctx.stroke();

        // 3. DRIFT TETHER (Connecting Truth to Visual)
        ctx.beginPath();
        ctx.moveTo(logicPos.x, logicY);
        ctx.lineTo(physX, physY);
        const drift = Vector.dist({x: logicPos.x, y: logicY}, {x: physX, y: physY});
        ctx.strokeStyle = drift > 20 ? '#ef4444' : 'rgba(255, 255, 255, 0.5)'; // Red if drift is high
        ctx.setLineDash([2, 2]);
        ctx.stroke();

        // 4. MOVEMENT INTENT (Next Grid Step)
        if (agent.path.length > 0) {
            const next = agent.path[0];
            const nextPx = HexUtils.toPx(next.q, next.r, engine.mapConfig);
            const nextH = grid.getTerrainHeight(next.q, next.r, engine);
            const nextY = VisualMath.getIsoVisualY(nextPx.y, nextH);

            ctx.strokeStyle = '#facc15'; // Yellow = Intent
            ctx.beginPath();
            ctx.moveTo(logicPos.x, logicY);
            ctx.lineTo(nextPx.x, nextY);
            ctx.stroke();

            ctx.fillStyle = '#facc15';
            ctx.beginPath(); ctx.arc(nextPx.x, nextY, 2, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }

    /**
     * Draws cinematic HUD elements when director target is active
     */
    public drawHUD(ctx: CanvasRenderingContext2D, engine: GameEngine, width: number, height: number, camera: RenderCamera, globalTime: number): void {
        if (!engine.directorTargetId) return;

        ctx.save();
        ctx.resetTransform();

        const pad = 40;
        const cornerSize = 25;

        ctx.strokeStyle = 'rgba(6, 182, 212, 0.4)';
        ctx.lineWidth = 1.5;

        // Top Left
        ctx.beginPath();
        ctx.moveTo(pad + cornerSize, pad);
        ctx.lineTo(pad, pad);
        ctx.lineTo(pad, pad + cornerSize);
        ctx.stroke();

        // Top Right
        ctx.beginPath();
        ctx.moveTo(width - pad - cornerSize, pad);
        ctx.lineTo(width - pad, pad);
        ctx.lineTo(width - pad, pad + cornerSize);
        ctx.stroke();

        // Bottom Left
        ctx.beginPath();
        ctx.moveTo(pad + cornerSize, height - pad);
        ctx.lineTo(pad, height - pad);
        ctx.lineTo(pad, height - pad - cornerSize);
        ctx.stroke();

        // Bottom Right
        ctx.beginPath();
        ctx.moveTo(width - pad - cornerSize, height - pad);
        ctx.lineTo(width - pad, height - pad);
        ctx.lineTo(width - pad, height - pad - cornerSize);
        ctx.stroke();

        const blink = Math.floor(globalTime * 2) % 2 === 0;
        if (blink) {
            ctx.fillStyle = '#ef4444';
            ctx.beginPath();
            ctx.arc(pad + 15, pad + 15, 5, 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
        ctx.font = 'bold 10px monospace';
        ctx.textAlign = 'left';
        ctx.fillText('DIRECTOR_CAM_FEED', pad + 25, pad + 18);
        ctx.fillText('SSOT_KERNEL_DEBUG', pad + 25, pad + 30);

        ctx.textAlign = 'right';
        ctx.fillText(`TRK_ID: ${engine.directorTargetId}`, width - pad - 5, height - pad - 10);

        ctx.restore();
    }

    public drawDebug(ctx: CanvasRenderingContext2D, fps: number): void {
        ctx.fillStyle = 'rgba(255,255,255,0.5)'; 
        ctx.font = '10px monospace';
        ctx.fillText(`FPS: ${fps}`, 10, 20);
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList } from "./RenderList";
import { RenderDispatcher } from "./RenderDispatcher";

export class RenderPipeline {
    private renderer: GameRenderer;
    private background = new BackgroundRenderer();
    private tactical = new TacticalRenderer();
    private hud = new HUDRenderer();
    private post = new PostProcessor();
    private renderList = new RenderList();

    // Transition State managed internally (SSOT)
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) { 
        this.renderer = renderer; 
    }

    public setTransitionPhase(phase: 'IN' | 'OUT' | 'IDLE') {
        if (this.transitionPhase !== phase) {
            this.transitionPhase = phase;
            // Reset progress when phase changes, unless going to IDLE
            if (phase !== 'IDLE') {
                this.transitionT = 0;
            }
        }
    }

    public update(dt: number, engine: GameEngine) { 
        this.tactical.update(dt, engine); 

        // Animation Logic moved from GameCanvas to here
        if (this.transitionPhase !== 'IDLE') {
            // Slower, weightier transition speed
            const speed = 0.5; 
            this.transitionT = Math.min(1.0, this.transitionT + dt * speed);
        } else {
            this.transitionT = 0;
        }
    }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, battleTime: number, realTime: number): void {
        const { width: pW, height: pH } = ctx.canvas;
        if (pW === 0 || pH === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const [lW, lH] = [pW / dpr, pH / dpr];
        const { mapConfig: cfg, currentScene: sc } = engine;

        // 1. Clear & Background
        ctx.resetTransform(); 
        ctx.fillStyle = '#020617'; 
        ctx.fillRect(0, 0, pW, pH);
        ctx.scale(dpr, dpr);
        // Background uses RealTime for ambient effects (stars, fog) even when game paused
        this.background.draw(ctx, lW, lH, sc, cfg, realTime);

        // 2. Main Scene (World Space)
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, lW, lH);
        // World objects use BattleTime to sync with logic
        this.drawWorld(ctx, engine, camera, highlight, hoveredHex, hoveredSkill, battleTime);

        // --- VISUAL SSOT CHECK ---
        // If director is active, draw the Logic vs Physics debug overlay in World Space
        if (engine.directorTargetId) {
            this.tactical.drawSSOTDebug(ctx, engine, engine.directorTargetId, this.renderer.grid, realTime);
        }

        ctx.restore(); 

        // 3. Post Processing
        let transAb = (this.transitionPhase !== 'IDLE') ? 4 * this.transitionT * (1 - this.transitionT) * 0.5 : 0;
        this.post.apply(ctx, pW, pH, this.renderer.camera.getTrauma(), transAb);

        // 4. Overlays (Screen/World Hybrid)
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, lW, lH);
        this.tactical.drawOverlay(ctx, engine, highlight, this.renderer.grid, realTime);
        this.hud.draw(ctx, this.renderer.hud, engine.agents, (q, r) => this.renderer.grid.getTerrainHeight(q, r, engine), cfg, highlight, battleTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tactical.drawHUD(ctx, engine, lW, lH, camera, realTime);
        this.tactical.drawDebug(ctx, fps);

        // 5. Global Transition/Finish Blur
        let blur = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blur = 1.0; 
        else if (this.transitionPhase === 'IN') blur = 1.0 - this.transitionT;
        if (blur > 0) this.post.applyFinishBlur(ctx, pW, pH, Math.max(0, Math.min(1, blur)));
    }

    private drawWorld(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, hoveredHex: Hex | null, hoveredSkill: Skill | null, t: number) {
        this.renderList.reset();
        const terrainH = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        const lW = ctx.canvas.width / (window.devicePixelRatio || 1);
        const lH = ctx.canvas.height / (window.devicePixelRatio || 1);

        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, t);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainH, engine.mapConfig, this.transitionT, this.transitionPhase, { width: lW, height: lH, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainH, t, highlight, engine.mapConfig);

        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            RenderDispatcher.dispatch(ctx, this.renderList.ops[i], engine.mapConfig.layout, t, this.renderer.unit);
        }

        const occluded = this.renderer.grid.getOccludedAgents(engine);
        if (occluded.length > 0) {
            ctx.save();
            occluded.forEach(a => this.renderer.unit.drawSilhouette(ctx, a, terrainH, t, engine.mapConfig));
            ctx.restore();
        }

        // [FIX] Pass layout to StatusOrchestrator
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, t, terrainH, engine.mapConfig.layout);
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { GameEngine, Agent } from '../../engine/game';
import { Team } from '../../types';
import { useDraggable } from '../../hooks/useDraggable';
import { Icons } from './icons';
import { HexUtils, Vector } from '../../engine/utils';

interface DirectorMonitorHUDProps {
    engine: GameEngine;
    onClose: () => void;
}

export const DirectorMonitorHUD: React.FC<DirectorMonitorHUDProps> = ({ engine, onClose }) => {
    const [targetAgent, setTargetAgent] = useState<Agent | null>(null);
    const [version, setVersion] = useState(0);
    const ref = useRef<HTMLDivElement>(null);
    const { dragHandlers, style, isDragging } = useDraggable(ref, {
        anchor: 'top-right',
        margin: 20
    });

    useEffect(() => {
        const interval = setInterval(() => {
            const ds = engine.state.director;
            if (ds.targetId) {
                const agent = engine.agents.find(a => a.id === ds.targetId);
                if (agent) {
                    setTargetAgent(agent);
                    setVersion(v => v + 1);
                }
            } else {
                setTargetAgent(null);
            }
        }, 50); // Higher refresh for physics metrics
        return () => clearInterval(interval);
    }, [engine]);

    if (!targetAgent) return null;

    const teamColor = targetAgent.team === Team.BLUE ? 'cyan' : 'red';
    const accentColor = targetAgent.team === Team.BLUE ? 'text-cyan-400' : 'text-red-500';
    const barColor = targetAgent.team === Team.BLUE ? 'bg-cyan-500' : 'bg-red-500';
    const borderColor = targetAgent.team === Team.BLUE ? 'border-cyan-500/50' : 'border-red-500/50';
    const glowColor = targetAgent.team === Team.BLUE ? 'rgba(6, 182, 212, 0.4)' : 'rgba(239, 68, 68, 0.4)';

    const hpPct = Math.max(0, targetAgent.hp / targetAgent.maxHp) * 100;
    const mpPct = Math.max(0, targetAgent.mp / targetAgent.maxMp) * 100;

    // --- SSOT Calculations ---
    const logicPos = HexUtils.toPx(targetAgent.q, targetAgent.r, engine.mapConfig);
    const physPos = { x: targetAgent.px, y: targetAgent.py };
    const drift = Vector.dist(logicPos, physPos);
    const speed = Math.sqrt(targetAgent.physics.vx ** 2 + targetAgent.physics.vy ** 2);

    return (
        <div 
            ref={ref}
            style={{...style, width: '300px'}}
            className="z-40 pointer-events-auto"
            {...dragHandlers}
        >
            <div className={`relative p-1 border-2 border-dashed ${borderColor} rounded-2xl transition-all duration-300 ${isDragging ? 'scale-105' : ''}`}>
                <div 
                    className="liquid-card !bg-slate-900/95 !rounded-xl p-5 border border-white/5 backdrop-blur-xl shadow-2xl"
                    style={{ boxShadow: `0 0 30px ${glowColor}` }}
                >
                    <div className="flex justify-between items-start mb-6">
                        <div className="flex flex-col gap-0.5">
                            <div className="flex items-center gap-2">
                                <div className={`w-2 h-2 rounded-full ${targetAgent.team === Team.BLUE ? 'bg-cyan-400' : 'bg-red-500'} animate-pulse`}></div>
                                <span className={`text-[11px] font-black tracking-widest ${accentColor}`}>TRK_LIVE: {targetAgent.id}</span>
                            </div>
                            <span className="text-[9px] font-bold text-slate-500 uppercase mt-1">Telemetry active // Signal strength: 98%</span>
                        </div>
                        <button 
                            onClick={onClose}
                            className="text-slate-500 hover:text-white transition-colors"
                        >
                            <Icons.Close className="w-3 h-3" />
                        </button>
                    </div>

                    <div className="space-y-4 mb-6">
                        <div className="space-y-1.5">
                            <div className="flex justify-between text-[9px] font-black text-slate-400">
                                <span>VITALITY (HP)</span>
                                <span className="font-mono">{Math.ceil(targetAgent.hp)} / {Math.ceil(targetAgent.maxHp)}</span>
                            </div>
                            <div className="h-2 w-full bg-black/40 rounded-full border border-white/5 overflow-hidden">
                                <div className={`h-full ${barColor} transition-all duration-300`} style={{ width: `${hpPct}%` }}></div>
                            </div>
                        </div>

                        <div className="space-y-1.5">
                            <div className="flex justify-between text-[9px] font-black text-slate-400">
                                <span>ENERGY (MP)</span>
                                <span className="font-mono text-blue-300">{Math.ceil(targetAgent.mp)} / {Math.ceil(targetAgent.maxMp)}</span>
                            </div>
                            <div className="h-1.5 w-full bg-black/40 rounded-full border border-white/5 overflow-hidden">
                                <div className="h-full bg-blue-500 transition-all duration-300" style={{ width: `${mpPct}%` }}></div>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 gap-3 pt-4 border-t border-white/10">
                        {/* Spatial Telemetry Section */}
                        <div className="flex flex-col gap-1">
                            <span className="text-[8px] font-black text-slate-600 uppercase tracking-widest">Spatial Telemetry (SSOT)</span>
                            <div className="grid grid-cols-2 gap-2 bg-black/40 p-2 rounded-lg border border-white/5">
                                <div className="flex flex-col">
                                    <span className="text-[9px] text-slate-500 font-mono">L-DRIFT</span>
                                    <span className={`text-xs font-mono font-bold ${drift > 20 ? 'text-red-400' : 'text-emerald-400'}`}>
                                        {drift.toFixed(2)}px
                                    </span>
                                </div>
                                <div className="flex flex-col border-l border-white/5 pl-2">
                                    <span className="text-[9px] text-slate-500 font-mono">VELOCITY</span>
                                    <span className="text-xs font-mono font-bold text-cyan-300">
                                        {speed.toFixed(0)} u/s
                                    </span>
                                </div>
                            </div>
                        </div>

                        <div className="flex flex-col gap-1">
                            <span className="text-[8px] font-black text-slate-600 uppercase tracking-widest">Logic State</span>
                            <div className="flex items-center justify-between bg-black/40 px-3 py-2 rounded-lg border border-white/5">
                                <span className="text-[10px] font-bold text-slate-400 uppercase">AI Task:</span>
                                <span className="text-[10px] font-mono font-bold text-cyan-300 truncate max-w-[120px]">
                                    {targetAgent.btStatus || 'IDLE_SCAN'}
                                </span>
                            </div>
                        </div>
                    </div>

                    <div className="mt-6 h-8 flex items-end gap-0.5 overflow-hidden opacity-30">
                        {Array.from({length: 20}).map((_, i) => (
                            <div 
                                key={i} 
                                className={`w-2 ${barColor} animate-pulse`} 
                                style={{ height: `${20 + Math.random() * 80}%`, animationDelay: `${i * 0.1}s` }}
                            ></div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

